  /** 按签号取（1–100）；越界返回 null，不瞎猜。 */
  function byNo(n) {
    var i = +n;
    if (!(i >= 1 && i <= LIST.length)) return null;
    var r = LIST[i - 1];
    return { 号: r[0], 名: r[1], 等: r[2], 吉凶: r[3], 宫: r[4], 诗: r[5], 意: r[6], 解: r[7], 圣: r[8] };
  }

  /** 按签名（典故名）模糊取，如「苏秦不第」。 */
  function byName(s) {
    var k = String(s || '');
    if (!k) return null;
    for (var i = 0; i < LIST.length; i++) if (LIST[i][1].indexOf(k) >= 0) return byNo(LIST[i][0]);
    return null;
  }

  return { LIST: LIST, count: LIST.length, byNo: byNo, byName: byName };
